// ── Production-grade fetch wrapper with retry, error handling ────
async function httpClient(baseUrl, defaultHeaders = {}) {
  async function request(method, path, body, retries = 3) {
    const options = {
      method,
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
        ...defaultHeaders,
      },
    };
    if (body !== undefined) options.body = JSON.stringify(body);

    for (let attempt = 1; attempt <= retries; attempt++) {
      let res;
      try {
        res = await fetch(`${baseUrl}${path}`, options);
      } catch (networkErr) {
        // Network-level failure (DNS error, connection refused)
        if (attempt === retries) throw networkErr;
        await sleep(2 ** attempt * 100); // exponential backoff
        continue;
      }

      // 5xx: safe to retry (server-side transient failure)
      if (res.status >= 500 && attempt < retries) {
        const retryAfter = res.headers.get('Retry-After');
        const delay = retryAfter ? Number(retryAfter) * 1000 : 2 ** attempt * 200;
        await sleep(delay);
        continue;
      }

      // 4xx: client error, never retry (fixing the request is needed)
      if (!res.ok) {
        const errorBody = await res.text().catch(() => '');
        const err = new Error(`HTTP ${res.status}: ${errorBody}`);
        err.status = res.status;
        throw err;
      }

      // 204 No Content — success with empty body
      if (res.status === 204) return null;
      return res.json();
    }
  }

  const sleep = ms => new Promise(r => setTimeout(r, ms));

  return {
    get:    (path)        => request('GET',    path),
    post:   (path, body)  => request('POST',   path, body),
    put:    (path, body)  => request('PUT',    path, body),
    patch:  (path, body)  => request('PATCH',  path, body),
    delete: (path)        => request('DELETE', path),
  };
}

